factorial.code:
func factorial(_ n: Int) -> Int {
    n <= 1 ? 1 : n * factorial(n - 1)
}

print(factorial(10))

fizzbuzz.code:
for i in 1...15 {
    switch (i % 3, i % 5) {
    case (0, 0): print("FizzBuzz")
    case (0, _): print("Fizz")
    case (_, 0): print("Buzz")
    default:     print(i)
    }
}

shapes.code:
protocol Shape {
    var area: Int { get }
}

struct Rectangle: Shape {
    let width, height: Int
    var area: Int { width * height }
}

struct Triangle: Shape {
    let base, height: Int
    var area: Int { base * height / 2 }
}

let shapes: [any Shape] = [Rectangle(width: 3, height: 4), Triangle(base: 10, height: 3)]
for shape in shapes {
    print("\(type(of: shape)): \(shape.area)")
}

signature.code:
// Optionals and enums with associated values: absence and alternatives
// live in the type system, and `switch` must handle every case.
enum Payment {
    case cash
    case card(last4: String)
    case voucher(code: String, discount: Int?)
}

func describe(_ p: Payment) -> String {
    switch p {
    case .cash:
        return "cash"
    case .card(let last4):
        return "card ending \(last4)"
    case .voucher(let code, let discount?):
        return "voucher \(code) (-\(discount)%)"
    case .voucher(let code, nil):
        return "voucher \(code)"
    }
}

let payments: [Payment] = [.cash, .card(last4: "4242"), .voucher(code: "SWIFT", discount: 10)]
for p in payments { print(describe(p)) }

let nickname: String? = nil
print("Hello, \(nickname ?? "guest")!")   // nil-coalescing unwraps safely
